const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const laSerena = ee.Geometry.Point([-71.2520, -29.9027]).buffer(50000); // 50km buffer around La Serena

  // Get current year and set date range for YTD (Jan 1 to July 7)
  const currentYear = new Date().getFullYear();
  const currentStart = currentYear + '-01-01';
  const currentEnd = currentYear + '-07-07';

  const historicalStart = '1990-01-01';
  const historicalEnd = '2020-07-07';

  // 2. Data Acquisition - CHIRPS precipitation data
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

  // Current year YTD precipitation
  const currentYTD = chirps
    .filterDate(currentStart, currentEnd)
    .filterBounds(laSerena);

  // Historical YTD precipitation (1990-2020)
  const historicalYTD = chirps
    .filterDate(historicalStart, historicalEnd)
    .filterBounds(laSerena);

  // Check if collections are empty
  const currentSize = currentYTD.size().getInfo();
  const historicalSize = historicalYTD.size().getInfo();

  console.log(`Current YTD (${currentYear}) images: ${currentSize}`);
  console.log(`Historical YTD (1990-2020) images: ${historicalSize}`);

  if (currentSize === 0 || historicalSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate total precipitation
  const currentSum = currentYTD.sum();
  const historicalSum = historicalYTD.sum();

  // Calculate mean of historical period
  const yearsInHistorical = 31; // 1990-2020 inclusive
  const historicalMean = historicalSum.divide(yearsInHistorical);

  // 4. Calculate regional means
  const currentPrecip = currentSum.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: laSerena,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation');

  const historicalMeanPrecip = historicalMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: laSerena,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation');

  const currentVal = currentPrecip.getInfo();
  const historicalVal = historicalMeanPrecip.getInfo();

  // Check for valid pixels
  if (currentVal === null || historicalVal === null) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failures
  if (!isFinite(currentVal) || !isFinite(historicalVal) || 
      currentVal < 0 || historicalVal < 0) {
    console.log("<answer>C3</answer>");
    return;
  }

  // 5. Validation & Final Answer
  console.log(`Current YTD (${currentYear}): ${currentVal.toFixed(1)} mm`);
  console.log(`Historical avg (1990-2020): ${historicalVal.toFixed(1)} mm`);
  console.log(`Difference: ${(currentVal - historicalVal).toFixed(1)} mm`);

  if (currentVal < historicalVal) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
